const response = $input.first().json;
const tasks = response.tasks || [];
const now = Date.now();

const overdue = [];
const today = [];
const inProgress = [];
const pending = [];

for (const task of tasks) {
  const dueDate = task.due_date ? parseInt(task.due_date) : null;
  const statusName = task.status?.status?.toLowerCase() || '';
  const assignees = (task.assignees || []).map(a => a.username).join(', ') || 'N/A';

  const entry = {
    name: task.name,
    list: task.list?.name || 'N/A',
    assignees,
    priority: task.priority?.priority || 'normal',
    dueDate: dueDate ? new Date(dueDate).toLocaleDateString('pt-BR') : 'Sem prazo',
    url: task.url || ''
  };

  if (dueDate && dueDate < now) {
    overdue.push(entry);
  } else if (statusName.includes('progress') || statusName.includes('andamento')) {
    inProgress.push(entry);
  } else if (dueDate) {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const todayEnd = new Date();
    todayEnd.setHours(23, 59, 59, 999);
    if (dueDate >= todayStart.getTime() && dueDate <= todayEnd.getTime()) {
      today.push(entry);
    } else {
      pending.push(entry);
    }
  } else {
    pending.push(entry);
  }
}

const summary = {
  date: new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' }),
  totalTasks: tasks.length,
  overdue: overdue.slice(0, 10),
  overdueCount: overdue.length,
  today: today.slice(0, 10),
  todayCount: today.length,
  inProgress: inProgress.slice(0, 10),
  inProgressCount: inProgress.length,
  pending: pending.slice(0, 10),
  pendingCount: pending.length
};

return [{ json: summary }];

